def migrate_share_intros(apps, old_news, new_news):
    ShareIntroEventsV2 = apps.get_model('api_v2', 'ShareIntroEvents')

    for old_share_intro_event in old_news.intro_event.all():
        ShareIntroEventsV2.objects.create(
            global_id=old_share_intro_event.global_id,
            profile_id=old_share_intro_event.profile_id,
            news_id=new_news.id,
            provider=old_share_intro_event.provider,
            is_closed=old_share_intro_event.is_closed,
            created_at=old_share_intro_event.created_at,
        )


def find_news_by_global_id(apps, global_id):
    """
    Searches for a news item by global_id in three models and returns a news item object if found.
    """
    PublisherNews = apps.get_model('api_v2', 'PublisherNews')
    UserNews = apps.get_model('api_v2', 'UserNews')
    CuratorNews = apps.get_model('api_v2', 'CuratorNews')

    for model in [PublisherNews, UserNews, CuratorNews]:
        news_item = model.objects.filter(global_id=global_id).first()
        if news_item:
            return news_item

    return None


def migrate_reports(apps):
    ReportsV1 = apps.get_model('api', 'NewsReport')
    ReportsV2 = apps.get_model('api_v2', 'Reports')
    ContentType = apps.get_model('contenttypes', 'ContentType')

    for old_report in ReportsV1.objects.all():
        news_item = find_news_by_global_id(apps, old_report.global_id)

        if not news_item:
            print(f"News with global_id {old_report.global_id} not found!")
            continue

        content_type = ContentType.objects.get_for_model(news_item, for_concrete_model=False)

        ReportsV2.objects.create(
            global_id=old_report.global_id,
            profile_id=old_report.profile_id,
            status=old_report.status,
            content_type=content_type,
            object_id=news_item.id
        )


def migrate_media_links(apps, media_link, content_object):
    MediaImage = apps.get_model('api_v2', 'MediaImage')
